CREATE TABLE IF NOT EXISTS gold_dev.quality.quality_events (
  event_id             STRING NOT NULL COMMENT 'Unique identifier of the quality event.',
  event_ts             TIMESTAMP NOT NULL COMMENT 'When the defect was recorded, in UTC.',
  site_code            STRING NOT NULL COMMENT 'Code of the site where the defect was found.',
  asset_id             STRING NOT NULL COMMENT 'Asset that produced the defective units.',
  defect_code          STRING NOT NULL COMMENT 'Code from the defect catalogue.',
  severity             STRING NOT NULL COMMENT 'Severity assigned at inspection.',
  quantity_affected    INT NOT NULL COMMENT 'Units affected by the defect.',
  inspector_pseudo_id  STRING NOT NULL COMMENT 'Salted hash of the inspector identifier. Never reversible in this table.',
  is_customer_reported BOOLEAN NOT NULL COMMENT 'True when the defect came from a customer complaint.',
  CONSTRAINT quality_events_pk PRIMARY KEY (event_id) NOT ENFORCED
)
USING DELTA
CLUSTER BY (site_code, event_ts)
LOCATION 'abfss://gold-shared@stbridgedev.dfs.core.windows.net/quality/quality_events'
COMMENT 'One row per defect recorded at an inspection point. The inspector is carried as a pseudonymous identifier only, so the table can be shared for analysis without exposing who recorded each event.'
TBLPROPERTIES (
  'delta.enableChangeDataFeed' = 'true',
  'contract.id' = 'quality_events',
  'contract.version' = '1.0.0'
);

